import{_ as r,o as e,c as l,a2 as a}from"./chunks/framework.DpXDHk3d.js";const u=JSON.parse('{"title":"苹果开发者账号申请文档","description":"","frontmatter":{},"headers":[],"relativePath":"any/ping-guo-kai-fa-zhe-zhang-hao-shen-qing-wen-dang.md","filePath":"any/ping-guo-kai-fa-zhe-zhang-hao-shen-qing-wen-dang.md","lastUpdated":1795661954000}'),o={name:"any/ping-guo-kai-fa-zhe-zhang-hao-shen-qing-wen-dang.md"};function d(n,t,p,i,s,h){return e(),l("div",null,[...t[0]||(t[0]=[a('<h1 id="苹果开发者账号申请文档" tabindex="-1">苹果开发者账号申请文档 <a class="header-anchor" href="#苹果开发者账号申请文档" aria-label="Permalink to &quot;苹果开发者账号申请文档&quot;">​</a></h1><blockquote><p>文档日期：2026-11-02 适用范围：以**中国大陆公司（法人实体）**身份申请 Apple Developer Program 年度会员（组织/公司开发者账号）。 信息口径：流程、时限与费用以 Apple 官网「注册 Apple 开发者计划」及 D-U-N-S 帮助页为准；社区经验与无法由官网直接核实的字段，显式标注「经验值 / 待核实」。 一句话结论：<strong>确认/申请邓白氏编码（免费）→ 备齐材料 → 官网在线注册（组织类型）→ 账户持有人身份验证（中国大陆必做，Apple Developer App 内）→ Apple 审核与授权核验 → 收到邮件 → 同意许可协议 → 支付年费（中国大陆约 ¥688/年）→ 开通使用。</strong> 顺利时全程约 1–2 周，卡点主要在邓白氏编码与 Apple 审核。</p></blockquote><hr><h2 id="_0-为什么要注册" tabindex="-1">0. 为什么要注册 <a class="header-anchor" href="#_0-为什么要注册" aria-label="Permalink to &quot;0. 为什么要注册&quot;">​</a></h2><p>仅在真机测试 App 用免费账户 + Xcode 即可；需要<strong>上架 App Store、TestFlight 内测、集成 App 内购买 / Apple Pay / iCloud / 推送等能力</strong>，或要以公司名义对外展示时，才需要付费年度会员。本文面向「公司」主体的注册。</p><h2 id="_1-账号类型-先想清楚注册哪种" tabindex="-1">1. 账号类型：先想清楚注册哪种 <a class="header-anchor" href="#_1-账号类型-先想清楚注册哪种" aria-label="Permalink to &quot;1. 账号类型：先想清楚注册哪种&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>显示给用户的供应商名称</th><th>注册渠道</th><th>适用场景</th></tr></thead><tbody><tr><td>个人（Individual）</td><td>个人法定姓名（不可用别名/昵称/公司名）</td><td>Apple Developer App 或网页</td><td>个人独立开发者，App 以个人名义上架</td></tr><tr><td><strong>组织（Organization，公司/非营利/合伙/合资/政府）</strong></td><td><strong>法人实体名称</strong>（如「供应商：XX 科技有限公司」）</td><td><strong>仅网页</strong></td><td>公司为主体、对外展示公司品牌、多人协作管理、合同制分发</td></tr><tr><td>Apple Developer Enterprise Program</td><td>法人实体名称</td><td>仅网页，需<strong>新建 Apple 账户</strong> + 单独身份验证</td><td>公司内部私密分发 App（MDM / 内网），年费 299 美元，一般公司不适用</td></tr></tbody></table><p>要点：</p><ul><li><strong>公司主体必须注册「组织」类型</strong>；个人独资企业 / 一人公司若无法按法人实体核验，Apple 会建议改按「个人」注册（见 6.3）。</li><li>Enterprise 计划与常规 App Store 分发互斥，绝大多数公司用普通 Developer Program 即可。</li><li>印度地区仅支持通过 Apple Developer App 注册；部分地区（如受制裁地区）不支持注册。</li></ul><h2 id="_2-前置条件与材料清单" tabindex="-1">2. 前置条件与材料清单 <a class="header-anchor" href="#_2-前置条件与材料清单" aria-label="Permalink to &quot;2. 前置条件与材料清单&quot;">​</a></h2><h3 id="_2-1-硬性前提" tabindex="-1">2.1 硬性前提 <a class="header-anchor" href="#_2-1-硬性前提" aria-label="Permalink to &quot;2.1 硬性前提&quot;">​</a></h3><table tabindex="0"><thead><tr><th>条件</th><th>要求</th><th>说明</th></tr></thead><tbody><tr><td>Apple 账户</td><td>开启<strong>双重认证</strong></td><td>建议用独立、长期使用的 Apple 账户作为开发者账户主体</td></tr><tr><td>法人实体</td><td>能承担法律责任的实体</td><td><strong>不接受</strong> DBA、虚构公司名称、商号或分公司</td></tr><tr><td>D-U-N-S 编号</td><td>唯一 9 位邓白氏编码</td><td>用于 Apple 核验公司身份；<strong>政府组织豁免</strong></td></tr><tr><td>签约授权人</td><td>法定代表人/创始人、高管、高级项目主管，或获授权员工</td><td>非法定代表人注册时需提供「法律联系人」佐证</td></tr><tr><td>工作邮箱</td><td><strong>公司域名</strong>邮箱</td><td>所有后续步骤邮件都发到这里，不能用个人邮箱</td></tr><tr><td>公司网站</td><td>公开、可访问、域名与公司关联</td><td>不接受社交媒体页、内容极少的占位页、域名注册机构页</td></tr></tbody></table><h3 id="_2-2-需要准备的材料" tabindex="-1">2.2 需要准备的材料 <a class="header-anchor" href="#_2-2-需要准备的材料" aria-label="Permalink to &quot;2.2 需要准备的材料&quot;">​</a></h3><table tabindex="0"><thead><tr><th>材料</th><th>用途</th><th>备注</th></tr></thead><tbody><tr><td>营业执照</td><td>D-U-N-S 申请 / 核验 / 授权核验</td><td>可能要求<strong>公证副本</strong>（市政窗口/公证处/律师公证，地区手续不同）</td></tr><tr><td>公司法定中文名 + 英文名</td><td>注册表单、D-U-N-S 查询</td><td>英文名与营业执照/官方口径一致；<strong>名称填错会直接延误审批</strong></td></tr><tr><td>公司注册地址 / 总部地址</td><td>D-U-N-S 申请</td><td>与营业执照一致</td></tr><tr><td>法定代表人姓名</td><td>注册表单</td><td>注册人非法定代表人时，另需「法律联系人」佐证授权</td></tr><tr><td>公司域名邮箱</td><td>接收 Apple 邮件</td><td>见 2.1</td></tr><tr><td>公司网站</td><td>组织身份核验</td><td>页面内容真实反映公司业务</td></tr><tr><td>联系电话</td><td>邓白氏/Apple 可能的电话核验</td><td>法人或负责人可接通的电话</td></tr><tr><td>注册人身份证 / 护照</td><td>账户持有人身份验证</td><td><strong>中国大陆账户持有人必做</strong>（见步骤 3）；身份证走手机验证，护照走扫描验证</td></tr></tbody></table><h2 id="_3-详细步骤" tabindex="-1">3. 详细步骤 <a class="header-anchor" href="#_3-详细步骤" aria-label="Permalink to &quot;3. 详细步骤&quot;">​</a></h2><h3 id="步骤-0-查询公司是否已有-d-u-n-s-编号-当日" tabindex="-1">步骤 0：查询公司是否已有 D-U-N-S 编号（当日） <a class="header-anchor" href="#步骤-0-查询公司是否已有-d-u-n-s-编号-当日" aria-label="Permalink to &quot;步骤 0：查询公司是否已有 D-U-N-S 编号（当日）&quot;">​</a></h3><ul><li>在 Apple 官方邓白氏查询工具 <a href="https://developer.apple.com/enroll/duns-lookup/" target="_blank" rel="noreferrer"><code>developer.apple.com/enroll/duns-lookup/</code></a> 按<strong>法律实体名称 + 总部地址</strong>查询。</li><li>查询到 → 记下编号，进入步骤 2。</li><li>查询不到 → 进入步骤 1 申请。</li></ul><h3 id="步骤-1-申请邓白氏编码-免费-下发最长约-5-个工作日" tabindex="-1">步骤 1：申请邓白氏编码（免费，下发最长约 5 个工作日） <a class="header-anchor" href="#步骤-1-申请邓白氏编码-免费-下发最长约-5-个工作日" aria-label="Permalink to &quot;步骤 1：申请邓白氏编码（免费，下发最长约 5 个工作日）&quot;">​</a></h3><ul><li>在邓白氏为 Apple 开发者提供的专用入口提交申请：<a href="https://support.dnb.com/?CUST=APPLEDEV" target="_blank" rel="noreferrer"><code>support.dnb.com/?CUST=APPLEDEV</code></a>。</li><li>提交信息：法律实体名称、总部地址、邮寄地址、工作联系人信息。</li><li>D&amp;B 可能电话回访补充信息（公司类型、员工人数等），<strong>备好营业执照</strong>。</li><li>时限：拿到编号最长 <strong>5 个工作日</strong>（加急无效）；编号同步给 Apple 最长 <strong>2 个工作日</strong>。<strong>超过 2 周未到位 → 邮件联系 D&amp;B</strong>（专用入口同上）。</li></ul><blockquote><p><strong>经验值</strong>：申请时公司英文名、地址务必与营业执照逐字一致，这是后续 Apple 核验能否通过的关键。</p></blockquote><h3 id="步骤-2-在线提交注册-组织类型" tabindex="-1">步骤 2：在线提交注册（组织类型） <a class="header-anchor" href="#步骤-2-在线提交注册-组织类型" aria-label="Permalink to &quot;步骤 2：在线提交注册（组织类型）&quot;">​</a></h3><ul><li>用开启双重认证的 Apple 账户登录 <a href="https://developer.apple.com/cn/programs/enroll/" target="_blank" rel="noreferrer"><code>developer.apple.com/cn/programs/enroll/</code></a>。</li><li>选择<strong>组织 / Company</strong> 注册，填写：法律实体名称、D-U-N-S 编号、地址、工作邮箱、网站、授权人信息。</li><li>⚠ <strong>组织注册不能当场付费</strong>：Apple 先核验，通过后邮件告知下一步（个人注册可在过程中直接完成购买）。</li></ul><h3 id="步骤-3-账户持有人身份验证-中国大陆账户持有人必做" tabindex="-1">步骤 3：账户持有人身份验证（中国大陆账户持有人必做） <a class="header-anchor" href="#步骤-3-账户持有人身份验证-中国大陆账户持有人必做" aria-label="Permalink to &quot;步骤 3：账户持有人身份验证（中国大陆账户持有人必做）&quot;">​</a></h3><ul><li>中国大陆的<strong>账户持有人必须完成身份验证</strong>（官方「身份验证」页明确要求），主要渠道是 <strong>Apple Developer App</strong>；无法使用 App 时联系 Apple Developer Support 走人工渠道。</li><li>验证方式（经验值）：<strong>中国身份证持有人 → 手机验证</strong>（姓名 + 身份证号核验）；无身份证 → <strong>护照扫描验证</strong>。</li><li>验证对象是<strong>账户持有人本人（即注册人）</strong>，不强制是法定代表人： <ul><li>法定代表人当注册人 → 法人本人做验证；</li><li>员工当注册人 → 员工本人做验证，法人/高管另以「法律联系人」身份接受核验（见步骤 4），<strong>法人通常无需亲自扫脸</strong>。</li></ul></li><li>注意：Apple 官方核验清单里<strong>没有「法人扫脸/人脸识别」环节</strong>。常见说法多混淆自国内安卓应用市场企业实名、工信部 App 备案人脸核验或第三方代办话术。</li></ul><h3 id="步骤-4-apple-审核与核验-通常-1-天–数日" tabindex="-1">步骤 4：Apple 审核与核验（通常 1 天–数日） <a class="header-anchor" href="#步骤-4-apple-审核与核验-通常-1-天–数日" aria-label="Permalink to &quot;步骤 4：Apple 审核与核验（通常 1 天–数日）&quot;">​</a></h3><ul><li><p>Apple 做两项核验：<strong>D-U-N-S 核验</strong> + <strong>签约授权核验</strong>。</p></li><li><p><strong>非法定代表人注册时需提供一名「法律联系人」</strong>，由其确认你是组织员工且拥有签约授权。Apple 会通过<strong>电话和/或邮件</strong>联系该联系人核实（核验通过后流程才继续）。需准备的信息（字段级细节为经验值）：</p><table tabindex="0"><thead><tr><th>法律联系人字段</th><th>要求</th></tr></thead><tbody><tr><td>姓名</td><td>建议填法定代表人、总经理或部门负责人</td></tr><tr><td>职务/职位</td><td>越高层越可信，建议高管/法务负责人</td></tr><tr><td>工作邮箱</td><td>必须<strong>公司域名</strong>邮箱</td></tr><tr><td>联系电话</td><td>审核期内保持可接通</td></tr><tr><td>与注册人的关系</td><td>写清楚，如「直属上级」，不要写含糊的「同事」</td></tr></tbody></table></li><li><p>若注册人本人就是法定代表人/创始人/高管，<strong>无需提供</strong>法律联系人。</p></li><li><p>可能要求补充<strong>公证的商业文件</strong>（证明复印件为原件真实副本）。</p></li></ul><h3 id="步骤-5-收到邮件-→-同意许可协议-→-付费" tabindex="-1">步骤 5：收到邮件 → 同意许可协议 → 付费 <a class="header-anchor" href="#步骤-5-收到邮件-→-同意许可协议-→-付费" aria-label="Permalink to &quot;步骤 5：收到邮件 → 同意许可协议 → 付费&quot;">​</a></h3><ul><li>核验通过后，Apple Developer Support 发送邮件说明后续步骤。</li><li>登录账户同意 <strong>Apple Developer Program 许可协议</strong>。</li><li>支付年费：中国大陆经 Apple Store 在线商店 / 网页端，约 <strong>¥688/年</strong>（当地币种计费；其他地区为 99 美元/年）。</li></ul><h3 id="步骤-6-开通与使用" tabindex="-1">步骤 6：开通与使用 <a class="header-anchor" href="#步骤-6-开通与使用" aria-label="Permalink to &quot;步骤 6：开通与使用&quot;">​</a></h3><ul><li>付款处理后收到确认邮件；登录 developer.apple.com 查看账户状态。</li><li>添加团队成员（People 中邀请成员并分配角色）。</li><li>在 App Store Connect 创建 App，配置 App ID / 证书 / Profile。</li></ul><h3 id="时间预估汇总" tabindex="-1">时间预估汇总 <a class="header-anchor" href="#时间预估汇总" aria-label="Permalink to &quot;时间预估汇总&quot;">​</a></h3><table tabindex="0"><thead><tr><th>阶段</th><th>时长</th></tr></thead><tbody><tr><td>邓白氏编码下发</td><td>最长 5 个工作日</td></tr><tr><td>邓白氏 → Apple 同步</td><td>最长 2 个工作日</td></tr><tr><td>账户持有人身份验证（App 内）</td><td>当日可完成（经验值）</td></tr><tr><td>Apple 组织核验</td><td>通常 1–3 个工作日（补充材料/电话核验会拉长）</td></tr><tr><td>付费后确认邮件</td><td>最长 24 小时（超时联系 Apple 支持，附<strong>注册 ID</strong>）</td></tr><tr><td><strong>合计（顺利）</strong></td><td><strong>约 1–2 周</strong></td></tr></tbody></table><h2 id="_4-费用" tabindex="-1">4. 费用 <a class="header-anchor" href="#_4-费用" aria-label="Permalink to &quot;4. 费用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>金额</th><th>说明</th></tr></thead><tbody><tr><td>Apple Developer Program 年费</td><td><strong>约 ¥688/年</strong>（中国大陆）/ 99 美元/年（其他地区）</td><td>当地币种计费，以官网显示为准</td></tr><tr><td>邓白氏编码</td><td><strong>免费</strong></td><td>大多数司法管辖区免费</td></tr><tr><td>发票（中国大陆）</td><td>—</td><td>致电 <strong>400-666-8800</strong> 联系 Apple Store 在线商店支持申请</td></tr><tr><td>退税 / 免税</td><td>—</td><td>订单号 + 免税表单发送至 <code>salestax@apple.com</code></td></tr></tbody></table><blockquote><p><strong>待核实</strong>：中国大陆 ¥688/年 为历年公开价格，实际以注册时官网/Apple Store 在线商店显示为准。</p></blockquote><h2 id="_5-常见失败原因与避坑" tabindex="-1">5. 常见失败原因与避坑 <a class="header-anchor" href="#_5-常见失败原因与避坑" aria-label="Permalink to &quot;5. 常见失败原因与避坑&quot;">​</a></h2><blockquote><p>本节为社区常见问题的经验汇总；凡属经验性结论标注「经验值」。</p></blockquote><ol><li><strong>公司名称填错 / 英文翻译不规范</strong> —— Apple 官网明示会延误审批（经验值：英文名与营业执照、邓白氏记录保持一致）。</li><li><strong>邓白氏信息与营业执照不一致</strong> —— 名称、地址、法人任一处不一致都可能核验失败。</li><li><strong>网站不合格</strong> —— 内容极少、占位页、域名与公司无关，直接被拒。</li><li><strong>邮箱不是公司域名</strong> —— 必须使用公司域名邮箱。</li><li><strong>个人独资 / 一人公司被判定「非法人」</strong> —— Apple 会建议改按个人注册（见 6.3）。</li><li><strong>注册人无签约授权</strong> —— 非法定代表人时未提供法律联系人，卡在授权核验。</li><li><strong>电话核验不接 / 答非所问</strong> —— 预留法人与负责人电话，审核期内保持可接通。</li><li><strong>账户持有人身份验证未通过</strong> —— 中国大陆账户持有人必须在 Apple Developer App 内完成验证；验证信息（姓名/证件号）与 Apple 账户实名信息不一致会卡住。</li><li><strong>误以为需要「法人扫脸」</strong> —— Apple 官方核验清单中没有扫脸/人脸识别环节；该说法多混淆自国内安卓应用市场企业实名或工信部 App 备案（见步骤 3 说明）。</li></ol><h2 id="_6-补充说明" tabindex="-1">6. 补充说明 <a class="header-anchor" href="#_6-补充说明" aria-label="Permalink to &quot;6. 补充说明&quot;">​</a></h2><h3 id="_6-1-组织注册-vs-个人注册怎么选" tabindex="-1">6.1 组织注册 vs 个人注册怎么选 <a class="header-anchor" href="#_6-1-组织注册-vs-个人注册怎么选" aria-label="Permalink to &quot;6.1 组织注册 vs 个人注册怎么选&quot;">​</a></h3><ul><li>用公司名义上架、多人协作、对外展示公司品牌 → <strong>组织</strong>。</li><li>仅个人开发者、App 以个人名义 → <strong>个人</strong>，成本更低、更快。</li></ul><h3 id="_6-2-注册后团队管理" tabindex="-1">6.2 注册后团队管理 <a class="header-anchor" href="#_6-2-注册后团队管理" aria-label="Permalink to &quot;6.2 注册后团队管理&quot;">​</a></h3><ul><li>组织账户可添加多个开发者成员；<strong>上架提交必须由组织自己完成</strong>（合同制开发者只能协助开发）。</li><li>员工内网安装自定 App → 用 Apple Business Manager。</li></ul><h3 id="_6-3-个人转组织-一人公司" tabindex="-1">6.3 个人转组织 / 一人公司 <a class="header-anchor" href="#_6-3-个人转组织-一人公司" aria-label="Permalink to &quot;6.3 个人转组织 / 一人公司&quot;">​</a></h3><ul><li>个人账号转组织账号：联系 Apple Developer Support 迁移。</li><li>一人公司（OPC）在 Apple 体系内按「法人实体」核验；若被判定为个人经营，则按个人注册。</li></ul><h3 id="_6-4-常见疑问" tabindex="-1">6.4 常见疑问 <a class="header-anchor" href="#_6-4-常见疑问" aria-label="Permalink to &quot;6.4 常见疑问&quot;">​</a></h3><ul><li><strong>Q：注册需要银行对公账户吗？</strong> A：付费走 Apple 渠道（信用卡 / Apple Store 在线商店），不强制对公账户；费用按当地币种计。</li><li><strong>Q：注册后能立刻上架吗？</strong> A：需在 App Store Connect 完成 App 创建与审核流程，与账号开通是两回事。</li><li><strong>Q：年费何时扣？</strong> A：年度会员、按年续费；网页注册按年购买，续费在官网账户或 App Store 处理。</li></ul><h2 id="_7-参考来源" tabindex="-1">7. 参考来源 <a class="header-anchor" href="#_7-参考来源" aria-label="Permalink to &quot;7. 参考来源&quot;">​</a></h2><ul><li><a href="https://developer.apple.com/cn/support/enrollment/" target="_blank" rel="noreferrer">Apple 官方 · 注册 Apple 开发者计划（中文）</a></li><li><a href="https://developer.apple.com/support/enrollment/" target="_blank" rel="noreferrer">Apple 官方 · 注册 Apple 开发者计划（英文）</a></li><li><a href="https://developer.apple.com/help/account/membership/D-U-N-S/" target="_blank" rel="noreferrer">Apple 官方 · D-U-N-S 帮助页</a></li><li><a href="https://developer.apple.com/cn/help/account/membership/identity-verification/" target="_blank" rel="noreferrer">Apple 官方 · 身份验证（中国大陆账户持有人必做）</a></li><li><a href="https://developer.apple.com/enroll/duns-lookup/" target="_blank" rel="noreferrer">Apple 官方 · 邓白氏查询工具</a></li><li><a href="https://developer.apple.com/cn/programs/" target="_blank" rel="noreferrer">Apple 官方 · 开发者计划权益与价格</a></li><li><a href="https://support.dnb.com/?CUST=APPLEDEV" target="_blank" rel="noreferrer">D&amp;B 官方 · Apple 开发者专用申请入口</a></li></ul>',49)])])}const c=r(o,[["render",d]]);export{u as __pageData,c as default};
